import{_ as t,o as a,c as r,a0 as d}from"./chunks/framework.iBgbCoJu.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/configuration.md","filePath":"guide/deployment/configuration.md"}'),o={name:"guide/deployment/configuration.md"};function s(i,e,n,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>All Hub services are configured via environment variables, managed by <code>envix</code> through each service&#39;s <code>ConfigModule</code>.</p><h2 id="common-variables" tabindex="-1">Common Variables <a class="header-anchor" href="#common-variables" aria-label="Permalink to &quot;Common Variables&quot;">​</a></h2><p>These variables are shared across all services:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>PORT</code></td><td>No</td><td>HTTP server port (default varies by service)</td></tr><tr><td><code>AUTHUP_URL</code></td><td>Yes</td><td>Authup identity provider URL</td></tr><tr><td><code>REDIS_URL</code></td><td>No</td><td>Redis connection URL (for pub/sub and caching)</td></tr><tr><td><code>AMQP_URL</code></td><td>No</td><td>RabbitMQ connection URL</td></tr></tbody></table><h2 id="database-variables" tabindex="-1">Database Variables <a class="header-anchor" href="#database-variables" aria-label="Permalink to &quot;Database Variables&quot;">​</a></h2><p>Used by <code>server-core</code>, <code>server-storage</code>, and <code>server-telemetry</code>:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_TYPE</code></td><td>Yes</td><td><code>mysql</code>, <code>postgres</code>, or <code>better-sqlite3</code></td></tr><tr><td><code>DB_HOST</code></td><td>Yes*</td><td>Database hostname</td></tr><tr><td><code>DB_PORT</code></td><td>Yes*</td><td>Database port</td></tr><tr><td><code>DB_USERNAME</code></td><td>Yes*</td><td>Database username</td></tr><tr><td><code>DB_PASSWORD</code></td><td>Yes*</td><td>Database password</td></tr><tr><td><code>DB_DATABASE</code></td><td>Yes</td><td>Database name (or <code>:memory:</code> for SQLite)</td></tr></tbody></table><p>*Not required for SQLite.</p><h3 id="sqlite-has-no-upgrade-path" tabindex="-1">SQLite has no upgrade path <a class="header-anchor" href="#sqlite-has-no-upgrade-path" aria-label="Permalink to &quot;SQLite has no upgrade path&quot;">​</a></h3><p>Migrations only run for <code>mysql</code> and <code>postgres</code>. On SQLite the schema is built from the entity classes by <code>synchronize()</code>, and only when no schema exists yet — so an <strong>existing</strong> SQLite database is never migrated or altered on upgrade.</p><p>Schema changes therefore break a persistent SQLite deployment. The rename of the <code>analysis</code> table to <code>analyses</code> is one such change: a SQLite database created before it keeps the old table, and queries against the new name fail.</p><p>Use SQLite only for tests and throwaway/in-memory (<code>:memory:</code>) instances. For any database you intend to keep, use MySQL or PostgreSQL. To carry an existing SQLite database across a schema change, export its data and re-import it into a freshly created database.</p><h2 id="storage-variables-server-storage" tabindex="-1">Storage Variables (server-storage) <a class="header-anchor" href="#storage-variables-server-storage" aria-label="Permalink to &quot;Storage Variables (server-storage)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>MINIO_ENDPOINT</code></td><td>Yes</td><td>MinIO/S3 endpoint URL</td></tr><tr><td><code>MINIO_ACCESS_KEY</code></td><td>Yes</td><td>S3 access key</td></tr><tr><td><code>MINIO_SECRET_KEY</code></td><td>Yes</td><td>S3 secret key</td></tr><tr><td><code>MINIO_USE_SSL</code></td><td>No</td><td>Enable SSL for MinIO connection</td></tr><tr><td><code>MINIO_PORT</code></td><td>No</td><td>MinIO port</td></tr></tbody></table><h2 id="telemetry-variables-server-telemetry" tabindex="-1">Telemetry Variables (server-telemetry) <a class="header-anchor" href="#telemetry-variables-server-telemetry" aria-label="Permalink to &quot;Telemetry Variables (server-telemetry)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>VICTORIA_LOGS_URL</code></td><td>Yes</td><td>VictoriaLogs endpoint URL</td></tr><tr><td><code>EVENT_RETENTION_DAYS</code></td><td>No</td><td>Days an audit/event row is kept before the daily sweep removes it (default <code>7</code>; <code>0</code> = keep forever)</td></tr></tbody></table><h2 id="frontend-variables-client-ui" tabindex="-1">Frontend Variables (client-ui) <a class="header-anchor" href="#frontend-variables-client-ui" aria-label="Permalink to &quot;Frontend Variables (client-ui)&quot;">​</a></h2><p>The full list lives in the <a href="./../../reference/frontend/#environment-variables">frontend reference</a>. One of them is a deployment decision rather than a service address:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>NUXT_PUBLIC_COOKIE_DOMAIN</code></td><td>No</td><td><code>Domain</code> attribute for the UI&#39;s session cookies. <strong>Leave empty.</strong></td></tr></tbody></table><h3 id="where-authup-is-served-matters" tabindex="-1">Where Authup is served matters <a class="header-anchor" href="#where-authup-is-served-matters" aria-label="Permalink to &quot;Where Authup is served matters&quot;">​</a></h3><p>The UI and Authup&#39;s own hosted pages persist their sessions under the <strong>same cookie names</strong>. If both can see each other&#39;s cookies, they hydrate, rotate and revoke each other&#39;s tokens, and the user is logged out on the next page reload.</p><p>Empty (host-only) cookies are correct in every layout. Setting a <code>Domain</code> delivers the cookies to every subdomain of that value — including Authup&#39;s host, if it sits below it. Serving Authup on a path of the UI&#39;s own origin additionally requires an Authup build containing <a href="https://github.com/authup/authup/issues/3495" target="_blank" rel="noreferrer">authup#3495</a>.</p><p>The layout matrix and the upgrade caveat are documented under <a href="./../../reference/frontend/#session-cookies">Session cookies</a>.</p>',24)])])}const p=t(o,[["render",s]]);export{u as __pageData,p as default};
